-- Migration 0067_court_document_network: generated by drizzle-kit (tables, column, indexes), RLS, grants and function hand-written, reviewed before commit.
-- Reviewed-by: Claude (agent, #485)
-- The court document network (#485, D-048): contributed_document is a global table (GLOBAL_TABLES, no
-- workspace column, no RLS) holding public court documents a workspace opted in to share; the app
-- role may SELECT, INSERT and UPDATE (blanking a withdrawn copy), never DELETE. contribution_ledger is
-- the tenant-side link (RLS) used by withdrawal and erasure. app_withdraw_contributions(workspace)
-- is SECURITY DEFINER because deciding whether another workspace still stands behind a copy needs to
-- see other workspaces' ledger rows; it only acts for the current app.workspace_id.
-- workspace_settings.contribute_public_court_documents defaults to false: nothing is shared unless opted in.
CREATE TABLE "contributed_document" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"source_id" text NOT NULL,
	"kind" text NOT NULL,
	"forum_label" text,
	"listing_date" date,
	"content" text,
	"sha256" text NOT NULL,
	"provenance" text DEFAULT 'contributed' NOT NULL,
	"contributed_at" timestamp with time zone DEFAULT now() NOT NULL,
	"retention_until" timestamp with time zone NOT NULL,
	"withdrawn_at" timestamp with time zone,
	CONSTRAINT "contributed_document_sha256_uq" UNIQUE("sha256"),
	CONSTRAINT "contributed_document_kind_chk" CHECK ("contributed_document"."kind" in ('cause_list', 'order')),
	CONSTRAINT "contributed_document_provenance_chk" CHECK ("contributed_document"."provenance" = 'contributed'),
	CONSTRAINT "contributed_document_sha256_chk" CHECK ("contributed_document"."sha256" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "contributed_document_withdrawn_chk" CHECK (("contributed_document"."withdrawn_at" is null) = ("contributed_document"."content" is not null))
);
--> statement-breakpoint
CREATE TABLE "contribution_ledger" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"contributed_document_id" uuid NOT NULL,
	"document_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "contribution_ledger_workspace_doc_uq" UNIQUE("workspace_id","contributed_document_id")
);
--> statement-breakpoint
ALTER TABLE "workspace_settings" ADD COLUMN "contribute_public_court_documents" boolean DEFAULT false NOT NULL;--> statement-breakpoint
ALTER TABLE "contributed_document" ADD CONSTRAINT "contributed_document_source_id_source_id_fk" FOREIGN KEY ("source_id") REFERENCES "public"."source"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "contribution_ledger" ADD CONSTRAINT "contribution_ledger_contributed_document_id_contributed_document_id_fk" FOREIGN KEY ("contributed_document_id") REFERENCES "public"."contributed_document"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
