CREATE POLICY "owner_definer_purge" ON "contribution_ledger" AS PERMISSIVE FOR DELETE TO causedeck_owner USING (true);--> statement-breakpoint
CREATE FUNCTION app_withdraw_contributions(p_workspace_id uuid)
  RETURNS integer
  LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public, pg_temp
  AS $$
  DECLARE
    v_docs uuid[];
    v_blanked integer;
  BEGIN
    IF p_workspace_id IS DISTINCT FROM nullif(current_setting('app.workspace_id', true), '')::uuid THEN
      RAISE EXCEPTION 'app_withdraw_contributions: workspace mismatch';
    END IF;
    SELECT coalesce(array_agg(contributed_document_id), '{}') INTO v_docs
      FROM contribution_ledger WHERE workspace_id = p_workspace_id;
    DELETE FROM contribution_ledger WHERE workspace_id = p_workspace_id;
    UPDATE contributed_document d SET content = NULL, withdrawn_at = now()
      WHERE d.id = ANY (v_docs) AND d.withdrawn_at IS NULL
        AND NOT EXISTS (SELECT 1 FROM contribution_ledger l WHERE l.contributed_document_id = d.id);
    GET DIAGNOSTICS v_blanked = ROW_COUNT;
    RETURN v_blanked;
  END
  $$;--> statement-breakpoint
REVOKE ALL ON FUNCTION app_withdraw_contributions(uuid) FROM PUBLIC;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app_withdraw_contributions(uuid) TO causedeck_app;
